import datetime, hashlib, json, pathlib, stat
F=pathlib.Path(__file__).absolute().parent
A=F.parent
R=F.parents[3]
O=A/'original_preparation_family'
def sha(b): return hashlib.sha256(b).hexdigest()
def dump(p,x): p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
def write(p,s): p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def row(p):
    assert p.is_file() and not p.is_symlink()
    b=p.read_bytes()
    return {'repo_path':p.relative_to(R).as_posix(),'bytes':len(b),'sha256':sha(b),'mode':format(stat.S_IMODE(p.stat().st_mode),'04o')}
def group(p):
    assert not p.is_symlink()
    return {'repo_path':p.relative_to(R).as_posix(),'rows':[row(x) for x in sorted(p.rglob('*')) if x.is_file()],
            'directories':[{'repo_path':x.relative_to(R).as_posix(),'mode':format(stat.S_IMODE(x.stat().st_mode),'04o')} for x in [p,*sorted(p.rglob('*'))] if x.is_dir()]}
